import { useState } from "react";
import { useAuth } from "../context/AuthContext";
import "../styles/login-ui.css";

export default function LoginPage() {
  const { login } = useAuth();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  return (
    <div className="login-wrapper">

      {/* LEFT – Login Form */}
      <div className="login-left">
        <h2>Digital Canteen Login</h2>

        <input
          placeholder="Username"
          value={username}
          onChange={e => setUsername(e.target.value)}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={e => setPassword(e.target.value)}
        />

        <button onClick={() => login(username, password)}>
          Login
        </button>

        <div className="login-hint">
          <p><b>Admin:</b> admin / admin@123</p>
          <p><b>User:</b> Any username & password</p>
        </div>
      </div>

      {/* RIGHT – Image Gallery */}
      <div className="login-right">
        <div className="image-grid">
          <img src="/images/canteen1.jpg" alt="canteen" />
          <img src="/images/canteen2.jpg" alt="canteen" />
          <img src="/images/canteen3.jpg" alt="canteen" />
          <img src="/images/canteen4.jpg" alt="canteen" />
        </div>
      </div>

    </div>
  );
}
